 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0], b[1] = min(b[0], y), max(b[1], y)
                    b[2], b[3] = min(b[2], x), max(b[3], x)
            colors = sorted(boxes, key=lambda k: (-(boxes[k][1]-boxes[k][0]+1)*(boxes[k][3]-boxes[k][2]+1), k))
            mapping = {a: b for a, b in zip(colors, reversed(colors))}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
